'use strict';
// Generated bytes: thread export (UTF-8 text) and statement (text-based PDF).
// Both depend only on the records they describe, so the same ledger yields the same bytes.
const c = require('./common.cjs');

function exportThread(data, t) {
  const f = c.formatter(data);
  const label = t.recipient.category ? t.recipient.category.replace('_', ' ') : 'clinic';
  const lines = [
    data.health_system.portal_name + ' - Secure message thread',
    'Thread: ' + t.thread_id,
    'Subject: ' + t.subject,
    'To: ' + t.recipient.display_name + ' (' + label + ')',
    'Status: ' + (t.status === 'closed' ? 'closed' + (t.closed_reason ? ' (' + t.closed_reason + ')' : '') : 'open' + (t.awaiting ? ', awaiting ' + t.awaiting : '')),
    'Opened: ' + f.stamp(c.parse(t.opened_at)),
    'Messages: ' + t.messages.length,
    ''.padEnd(72, '-')
  ];
  for (const m of t.messages) {
    lines.push('[' + f.stamp(c.parse(m.at)) + '] ' + m.author.display_name + ' (' + m.author.role.replace('_', ' ') + ')');
    lines.push(m.body);
    if (m.attachments.length) lines.push('Attachments: ' + m.attachments.length + ' (' + m.attachments.join(', ') + ')');
    lines.push('');
  }
  return c.file('northlake-thread-' + t.thread_id + '.txt', 'text/plain', Buffer.from(lines.join('\n') + '\n', 'utf8'));
}

function statementLines(data, s) {
  const f = c.formatter(data), hs = data.health_system, p = data.patient;
  const col = (text, width, right = false) => {text = String(text); if (text.length > width) text = text.slice(0, width - 1) + '~'; return right ? text.padStart(width) : text.padEnd(width);};
  const lines = [
    hs.name.toUpperCase() + ' - PATIENT STATEMENT',
    'Statement ' + s.statement_id + '   Period ' + f.dayLabel(s.period_start) + ' to ' + f.dayLabel(s.period_end),
    'Generated ' + f.stamp(c.parse(s.generated_at)),
    '',
    'Patient: ' + p.name + '   MRN ' + p.mrn + '   DOB ' + p.date_of_birth,
    'Address: ' + p.address.line1 + (p.address.line2 ? ', ' + p.address.line2 : '') + ', ' + p.address.city + ', ' + p.address.state + ' ' + p.address.postal_code,
    'Insurance: ' + p.insurance.plan_name + ' (' + p.insurance.payer + ')   Member ' + p.insurance.member_id + (p.insurance.group_number ? '   Group ' + p.insurance.group_number : ''),
    'Billing office: ' + hs.billing_phone + '   ' + hs.billing_hours,
    '',
    'ITEMIZED CHARGES',
    col('Date', 11) + col('Claim', 14) + col('Description', 30) + col('Billed', 11, true) + col('Ins adj', 11, true) + col('Ins paid', 11, true) + col('You owe', 11, true) + col('Paid', 11, true) + col('Balance', 11, true),
    ''.padEnd(121, '-')
  ];
  const claims = s.claim_ids.map(id => c.claim(data, id)).sort((a, b) => a.service_date.localeCompare(b.service_date) || a.claim_id.localeCompare(b.claim_id));
  const totals = {billed:0, adj:0, ins:0, owe:0, paid:0, bal:0};
  for (const cl of claims) {
    const paid = Math.max(0, c.paidByPatient(data, cl.claim_id)), bal = c.openBalance(data, cl);
    const pending = !c.FINAL.has(cl.status);
    lines.push(col(cl.service_date, 11) + col(cl.claim_id, 14) + col(cl.description, 30) + col(c.money(cl.billed_cents), 11, true) +
      col(pending ? 'pending' : c.money(cl.insurance_adjustment_cents), 11, true) + col(pending ? 'pending' : c.money(cl.insurance_paid_cents), 11, true) +
      col(pending ? 'pending' : c.money(cl.patient_responsibility_cents), 11, true) + col(c.money(paid), 11, true) + col(pending ? '-' : c.money(bal), 11, true));
    if (cl.status === 'denied') lines.push(col('', 25) + 'Denied by insurer: ' + (cl.reason_code || 'no reason code'));
    if (cl.status === 'reprocessing') lines.push(col('', 25) + 'Resubmitted to insurer; decision pending');
    totals.billed += cl.billed_cents; totals.adj += pending ? 0 : cl.insurance_adjustment_cents; totals.ins += pending ? 0 : cl.insurance_paid_cents;
    totals.owe += pending ? 0 : cl.patient_responsibility_cents; totals.paid += paid; totals.bal += bal;
  }
  lines.push(''.padEnd(121, '-'));
  lines.push(col('TOTALS', 55) + col(c.money(totals.billed), 11, true) + col(c.money(totals.adj), 11, true) + col(c.money(totals.ins), 11, true) + col(c.money(totals.owe), 11, true) + col(c.money(totals.paid), 11, true) + col(c.money(totals.bal), 11, true));
  lines.push('');
  lines.push('PAYMENTS AND REFUNDS THIS PERIOD');
  const payments = s.payment_ids.map(id => c.byId(data.payments, 'payment_id', id, 'Payment')).sort((a, b) => a.at.localeCompare(b.at));
  if (!payments.length) lines.push('  None');
  for (const pm of payments) lines.push('  ' + col(f.day(c.parse(pm.at)), 12) + col(pm.kind === 'refund' ? 'Refund' : 'Payment', 9) + col(pm.method.replace(/_/g, ' ') + (pm.last4 ? ' ending ' + pm.last4 : ''), 32) + col((pm.kind === 'refund' ? '-' : '') + c.money(pm.amount_cents), 12, true) + '  ' + pm.confirmation_number);
  lines.push('');
  lines.push('BALANCE DUE: ' + c.money(s.balance_due_cents) + (s.past_due_cents > 0 ? '   PAST DUE: ' + c.money(s.past_due_cents) : ''));
  if (s.past_due_note) lines.push('Balances more than ' + hs.past_due_after_days + ' days past due may be referred to collections. Questions: ' + hs.billing_phone + '.');
  lines.push('Charges still with your insurer are not due yet and appear as pending.');
  lines.push('Pay online in ' + hs.portal_name + ' under Billing, or call the billing office.');
  return lines;
}

// Minimal PDF 1.4 writer: Courier text, one content stream per page, classic cross-reference table.
function pdf(lines, {fontSize = 8, leading = 10.5, perPage = 64} = {}) {
  const esc = s => s.replace(/[^\x20-\x7e]/g, '?').replace(/\\/g, '\\\\').replace(/\(/g, '\\(').replace(/\)/g, '\\)');
  const pages = [];
  for (let i = 0; i < Math.max(1, lines.length); i += perPage) pages.push(lines.slice(i, i + perPage));
  const objects = [];
  const add = body => {objects.push(body); return objects.length;};
  const catalog = add(null), pagesId = add(null), font = add('<< /Type /Font /Subtype /Type1 /BaseFont /Courier >>');
  const pageIds = [];
  for (const page of pages) {
    const content = 'BT /F1 ' + fontSize + ' Tf ' + leading + ' TL 36 756 Td ' + page.map(l => '(' + esc(l) + ') Tj T*').join(' ') + ' ET';
    const stream = add('<< /Length ' + Buffer.byteLength(content, 'latin1') + ' >>\nstream\n' + content + '\nendstream');
    pageIds.push(add('<< /Type /Page /Parent ' + pagesId + ' 0 R /MediaBox [0 0 612 792] /Contents ' + stream + ' 0 R /Resources << /Font << /F1 ' + font + ' 0 R >> >> >>'));
  }
  objects[catalog - 1] = '<< /Type /Catalog /Pages ' + pagesId + ' 0 R >>';
  objects[pagesId - 1] = '<< /Type /Pages /Kids [' + pageIds.map(i => i + ' 0 R').join(' ') + '] /Count ' + pageIds.length + ' >>';
  let out = '%PDF-1.4\n%\xe2\xe3\xcf\xd3\n';
  const offsets = [];
  objects.forEach((body, i) => {offsets.push(Buffer.byteLength(out, 'latin1')); out += (i + 1) + ' 0 obj\n' + body + '\nendobj\n';});
  const xref = Buffer.byteLength(out, 'latin1');
  out += 'xref\n0 ' + (objects.length + 1) + '\n0000000000 65535 f \n' + offsets.map(o => String(o).padStart(10, '0') + ' 00000 n \n').join('') +
    'trailer\n<< /Size ' + (objects.length + 1) + ' /Root ' + catalog + ' 0 R >>\nstartxref\n' + xref + '\n%%EOF\n';
  return Buffer.from(out, 'latin1');
}

const statementPdf = (data, s) => c.file(s.filename, 'application/pdf', pdf(statementLines(data, s)));

module.exports = {exportThread, statementPdf, statementLines, pdf};
